-- =============================================================
--  CINESIC — seed_boxoffice.sql
--  Real box office financial data for all 150 movies
--  Run AFTER seed_movies.sql
--  Triggers will auto-set club flags after each INSERT
-- =============================================================

USE cinesic;

-- =============================================================
--  BOX_OFFICE
--  All USD values. india_gross_inr stored in paise×100
--  (i.e. ₹100 Cr = 10,000,000,000)
--  roi_pct = (total_revenue - total_cost) / total_cost * 100
--  verdict: Blockbuster/Super Hit/Hit/Average/Flop/Disaster
-- =============================================================

INSERT INTO box_office
  (movie_id,
   budget_usd, production_cost_usd, marketing_cost_usd, distribution_cost_usd, total_cost_usd,
   opening_day_usd, opening_weekend_usd,
   domestic_gross_usd, overseas_gross_usd, worldwide_gross_usd,
   ott_deal_usd, satellite_rights_usd, music_rights_usd, total_revenue_usd,
   india_gross_inr,
   us_opening_weekend, china_gross_usd, uk_gross_usd,
   profit_loss_usd, roi_pct, break_even_weeks, verdict)
