-- =============================================================
--  Verification — top 10 by worldwide gross
-- =============================================================
SELECT 'seed_boxoffice.sql complete' AS status;
SELECT COUNT(*) AS total_bo_records FROM box_office;

SELECT m.title, b.worldwide_gross_usd,
       ROUND(b.india_gross_inr/10000000,0) AS india_gross_cr,
       b.roi_pct, b.verdict
FROM box_office b
JOIN movies m ON b.movie_id = m.movie_id
ORDER BY b.worldwide_gross_usd DESC
LIMIT 15;
